use super::*;
use semio_s_artifact_layout_layout_model::{Layer,PageMargins,PageColumns};
struct Source<'a>{value:&'a serde_json::Value,identity:usize}
impl PageLayerCacheSource for Source<'_>{fn identity(&self)->usize{self.identity}fn layer_count(&self)->usize{self.value["layers"].as_array().unwrap().len()}fn layer_id(&self,index:usize)->&str{self.value["layers"][index].as_str().unwrap()}fn frame_count(&self)->usize{self.value["frames"].as_array().unwrap().len()}fn frame_id(&self,index:usize)->&str{self.value["frames"][index]["id"].as_str().unwrap()}fn frame_layer_id(&self,index:usize)->&str{self.value["frames"][index]["layer"].as_str().unwrap()}}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn observe(g:RetainedCloneGrant,f:impl FnOnce()->RetainedCloneStep)->RetainedCloneStep{let(step,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(f);assert!(!heap.overflowed);assert_eq!(heap.requested_bytes,step.progress().retained_capacity_bytes);assert_eq!(heap.released_bytes,step.progress().released_bytes);assert!(step.progress().fits(g));step}
fn denied(g:RetainedCloneGrant,axis:usize)->Option<RetainedCloneGrant>{let mut out=g;let value=match axis{0=>&mut out.maximum_items,1=>&mut out.maximum_copy_bytes,2=>&mut out.maximum_capacity_bytes,3=>&mut out.maximum_release_bytes,_=>&mut out.maximum_depth};if *value==0{None}else{*value-=1;Some(out)}}
fn page(s:&impl PageLayerCacheSource)->Page{Page{id:"page".into(),name:String::new(),spread_id:"spread".into(),parent_page_id:None,width:100.0,height:100.0,margins:PageMargins{top:0.0,right:0.0,bottom:0.0,left:0.0},columns:PageColumns{count:1,gutter:0.0},guides:Vec::new(),layer_ids:vec!["old-layer".repeat(1000)],layers:(0..s.layer_count()).map(|i|Layer{id:s.layer_id(i).into(),name:String::new(),visible:true,locked:false,object_ids:vec!["old-object".repeat(1000)]}).collect(),frames:Vec::new(),overrides:Vec::new(),background_drawing:None}}
fn close(p:&mut PageCachePreparation){p.begin_close();for turn in 0..100000{if p.terminal_is_empty(){return}let d=p.close_demand(4096).unwrap();for axis in 0..5{if let Some(g)=denied(grant(d),axis){assert_eq!(observe(g,||p.close_step(g).unwrap()).progress(),Default::default());}}let step=observe(grant(d),||p.close_step(grant(d)).unwrap());assert!(step.progress().fits(grant(d)));assert!(turn<99999);}panic!("cache original retirement stalled")}
#[test]
fn shared_cache_corpus_preserves_order_and_original_grants(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for value in corpus["cases"].as_array().unwrap(){let source=Source{value,identity:1};let mut p=PageCachePreparation::new();for turn in 0..100000{if p.is_ready(){break}let d=p.demand(&source).unwrap();for axis in 0..5{if let Some(g)=denied(grant(d),axis){let before=p.control;assert_eq!(observe(g,||p.advance(&source,g).unwrap()).progress(),Default::default());assert_eq!(p.control.phase,before.phase);assert_eq!(p.control.index,before.index);assert_eq!(p.control.copy_offset,before.copy_offset);}}let step=observe(grant(d),||p.advance(&source,grant(d)).unwrap());assert!(step.progress().fits(grant(d)));assert!(turn<99999);}assert!(p.is_ready());let mut out=page(&source);let original_pointer=out.layers.first().map(|layer|layer.id.as_ptr());let old_layer_pointer=out.layer_ids[0].as_ptr();for turn in 0..=source.layer_count(){let d=p.install_demand().unwrap();for axis in[0,1,4]{assert_eq!(p.install_owned(&mut out,denied(grant(d),axis).unwrap()).unwrap().progress(),Default::default());}let step=observe(grant(d),||p.install_owned(&mut out,grant(d)).unwrap());assert!(step.progress().fits(grant(d)));assert_eq!(matches!(step,RetainedCloneStep::Complete(_)),turn==source.layer_count());if turn==0{assert_eq!(p.owners().layer_ids[0].as_ptr(),old_layer_pointer);}}assert_eq!(serde_json::to_value(&out.layer_ids).unwrap(),value["expected"]["layerIds"]);for(i,layer)in out.layers.iter().enumerate(){assert_eq!(serde_json::to_value(&layer.object_ids).unwrap(),value["expected"]["objectIds"][i]);}assert_eq!(out.layers.first().map(|layer|layer.id.as_ptr()),original_pointer);close(&mut p);}}
#[test]
fn preparation_cancel_and_source_replacement_remain_funded_closeable(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let value=&corpus["cases"][5];for cut in[0,1,7,31,97,211,503]{let source=Source{value,identity:1};let mut p=PageCachePreparation::new();for _ in 0..cut{if p.is_ready(){break}let d=p.demand(&source).unwrap();p.advance(&source,grant(d)).unwrap();}if cut>0{assert!(p.demand(&Source{value,identity:2}).is_err());}close(&mut p);}}

#[test]
fn partial_cache_installation_retains_every_displaced_owner_for_funded_close(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();let value=&corpus["cases"][5];for cut in 0..=3{let source=Source{value,identity:1};let mut p=PageCachePreparation::new();while !p.is_ready(){let d=p.demand(&source).unwrap();observe(grant(d),||p.advance(&source,grant(d)).unwrap());}let mut out=page(&source);for _ in 0..cut{let d=p.install_demand().unwrap();observe(grant(d),||p.install_owned(&mut out,grant(d)).unwrap());}close(&mut p);}}

#[test]
fn prepared_parent_installs_preserve_original_row_headers_and_displaced_cache_custody(){let corpus:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();for target in corpus["preparedParentCases"].as_array().unwrap(){let value=&corpus["cases"][target["caseIndex"].as_u64().unwrap()as usize];let source=Source{value,identity:19};let original=page(&source);let mut parent=ParentPage{id:original.id,name:original.name,width:original.width,height:original.height,layer_ids:original.layer_ids,layers:original.layers,frames:original.frames};let layer_pointer=parent.layers.first().map(|layer|layer.id.as_ptr());let old_layer=parent.layer_ids[0].as_ptr();let old_objects=parent.layers.iter().map(|layer|layer.object_ids[0].as_ptr()).collect::<Vec<_>>();let mut p=PageCachePreparation::new();while !p.is_ready(){let d=p.demand(&source).unwrap();observe(grant(d),||p.advance(&source,grant(d)).unwrap());}for at in 0..=source.layer_count(){let d=p.install_demand().unwrap();for axis in 0..5{if let Some(g)=denied(grant(d),axis){assert_eq!(observe(g,||p.install_prepared_parent(&mut parent,g).unwrap()).progress(),Default::default());}}let step=observe(grant(d),||p.install_prepared_parent(&mut parent,grant(d)).unwrap());assert_eq!(matches!(step,RetainedCloneStep::Complete(_)),at==source.layer_count());if at==0{assert_eq!(p.owners().layer_ids[0].as_ptr(),old_layer)}else{assert_eq!(p.owners().objects[at-1][0].as_ptr(),old_objects[at-1])}}assert_eq!(parent.layers.first().map(|layer|layer.id.as_ptr()),layer_pointer);assert_eq!(serde_json::to_value(&parent.layer_ids).unwrap(),value["expected"]["layerIds"]);for(i,layer)in parent.layers.iter().enumerate(){assert_eq!(serde_json::to_value(&layer.object_ids).unwrap(),value["expected"]["objectIds"][i]);}close(&mut p);}}
